    "{\"name\":\"search_music\",\"description\":\"Search Zing MP3 for up to five songs by title and artist; returns exact song ids.\","
    "\"parameters\":{\"type\":\"OBJECT\",\"properties\":{\"query\":{\"type\":\"STRING\"}},\"required\":[\"query\"]}},"
    "{\"name\":\"offer_music\",\"description\":\"Propose an exact id from the latest search results. Returns authoritative title and artist. Speak both, ask if it is the right song, then WAIT for next user turn. Never starts music.\","
    "\"parameters\":{\"type\":\"OBJECT\",\"properties\":{\"id\":{\"type\":\"STRING\"}},\"required\":[\"id\"]}},"
    "{\"name\":\"play_music\",\"description\":\"Play ONLY the exact offered track after its title/artist were spoken and the NEXT real user turn confirms it by meaning. No implied consent, no same-turn play. Rejects expired/changed/unconfirmed tracks. Closes voice session to play; failures do not substitute songs.\","
    "\"parameters\":{\"type\":\"OBJECT\",\"properties\":{\"id\":{\"type\":\"STRING\"}},\"required\":[\"id\"]}},"
    "{\"name\":\"play_next_music\",\"description\":\"Only after Chat resumes from finished music AND a NEW real user request to continue/next: choose a DIFFERENT exact id from available choices or new search results and play immediately, no proposal/confirmation needed. Never call on silence or automatically; named new songs still require offer_music.\","
    "\"parameters\":{\"type\":\"OBJECT\",\"properties\":{\"id\":{\"type\":\"STRING\"}},\"required\":[\"id\"]}},"
    "{\"name\":\"stop_music\",\"description\":\"Stop any pending or playing song.\"},"
    "{\"name\":\"get_network_status\",\"description\":\"Read current Wi-Fi connection, SSID, IP, signal and last observed Internet state without scanning or reconnecting.\"},"
    "{\"name\":\"get_system_info\",\"description\":\"Read firmware, ESP-IDF version, uptime, free internal RAM and PSRAM, and screen dimensions.\"},"
    "{\"name\":\"get_wallpaper\",\"description\":\"Read whether the single uploaded wallpaper exists. It is used automatically; missing/invalid media falls back to the black/white theme background. Upload replacements in Setting. No built-in image or selection tool.\"},"
    "{\"name\":\"request_reboot\",\"description\":\"Prepare reboot, then ask for explicit confirmation in a separate user turn within 60 seconds. Does not reboot.\"},"
    "{\"name\":\"confirm_reboot\",\"description\":\"Reboot only after a pending request and a new user utterance explicitly confirming reboot.\"},"
    "{\"name\":\"get_device_settings\",\"description\":\"Read volume, brightness, speaker state, theme and screen timeout.\"},"
    "{\"name\":\"end_conversation\",\"description\":\"Arm closure AFTER your final spoken reply finishes. Use for goodbye/stop, or when the user declines your offer of further help. Call first, then speak one brief closing sentence and finish your turn, with no follow-up question. Do not use for unrelated negative answers or song rejection.\"},"
    "{\"name\":\"set_volume\",\"description\":\"Set speaker volume to an absolute integer percent from 0 to 100.\","
    "\"parameters\":{\"type\":\"OBJECT\",\"properties\":{\"percent\":{\"type\":\"INTEGER\"}},\"required\":[\"percent\"]}},"
    "{\"name\":\"set_brightness\",\"description\":\"Set display brightness to an absolute integer percent from 10 to 100.\","
    "\"parameters\":{\"type\":\"OBJECT\",\"properties\":{\"percent\":{\"type\":\"INTEGER\"}},\"required\":[\"percent\"]}},"
    "{\"name\":\"set_theme\",\"description\":\"Switch the device display theme.\","
    "\"parameters\":{\"type\":\"OBJECT\",\"properties\":{\"theme\":{\"type\":\"STRING\",\"enum\":[\"dark\",\"light\"]}},\"required\":[\"theme\"]}},"
    "{\"name\":\"set_speaker\",\"description\":\"Enable or mute the device speaker.\","
    "\"parameters\":{\"type\":\"OBJECT\",\"properties\":{\"enabled\":{\"type\":\"BOOLEAN\"}},\"required\":[\"enabled\"]}},"
    "{\"name\":\"set_screen_timeout\",\"description\":\"Set idle screen timeout in seconds; zero means always on.\","
    "\"parameters\":{\"type\":\"OBJECT\",\"properties\":{\"seconds\":{\"type\":\"INTEGER\",\"description\":\"One of 0, 30, 60, 120, 300, 600.\"}},\"required\":[\"seconds\"]}},"
    "{\"name\":\"set_flashlight\",\"description\":\"Turn the Hisu flashlight on or off.\","
    "\"parameters\":{\"type\":\"OBJECT\",\"properties\":{\"enabled\":{\"type\":\"BOOLEAN\"}},\"required\":[\"enabled\"]}}"
    "]}]}}";
